param([Parameter(Mandatory=$true)][string]$RunnerDirectory,[Parameter(Mandatory=$true)][ValidateSet('generate','verify','compare','cancel-pre','cancel-mid')][string]$Mode,[Parameter(Mandatory=$true)][string]$Inputs,[Parameter(Mandatory=$true)][string]$Evidence,[string]$ManifestSha256,[int]$Trials=1,[int]$CancelMilliseconds=50,[switch]$PreparationSelfCheck)
# Controller-only asynchronous launch. Worker prepares this request but never starts full jobs.
$ErrorActionPreference='Stop';$runnerPath=(Resolve-Path -LiteralPath $RunnerDirectory).Path;$inputsPath=[IO.Path]::GetFullPath($Inputs);$evidencePath=[IO.Path]::GetFullPath($Evidence)
if(Test-Path -LiteralPath $evidencePath){throw 'Evidence already exists; no overwrite/retry.'}
$pinPath=Join-Path $runnerPath 'pin.json';$pin=Get-Content -LiteralPath $pinPath -Raw|ConvertFrom-Json
foreach($file in $pin.Files){$path=Join-Path $runnerPath $file.File;if((Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash -ne $file.Sha256){throw "Pinned executable changed: $($file.File)"}}
if($Mode -ne 'generate'){if([string]::IsNullOrWhiteSpace($ManifestSha256)){throw 'Comparison/verify/cancellation require the retained manifest SHA256.'};if((Get-FileHash -LiteralPath (Join-Path $inputsPath 'manifest.json') -Algorithm SHA256).Hash -ne $ManifestSha256){throw 'Input manifest identity differs.'}}
if($PreparationSelfCheck){if($Mode -eq 'generate'){throw 'Preparation self-check generation uses runner selfcheck mode, never full launch.'};$small=Get-Content -LiteralPath (Join-Path $inputsPath 'RawAutomatic-inputs.json') -Raw|ConvertFrom-Json;if($small.snapshot.imported.Count -gt 3 -or @($small.snapshot.imported|Where-Object {$_.metadata.frame_count -gt 24}).Count -gt 0){throw 'Preparation self-check must stay at most3x24.'}}
$launchPath=$evidencePath+'-controller-launch';if(Test-Path -LiteralPath $launchPath){throw 'Launch receipt already exists.'};New-Item -ItemType Directory -Path $launchPath|Out-Null
$arguments=@('--mode',$Mode,'--inputs',$inputsPath,'--evidence',$evidencePath,'--controller-owned','true','--trials',"$Trials",'--cancel-ms',"$CancelMilliseconds")
if($Mode -eq 'generate'){$arguments+=@('--recordings','30','--frames','1879')}else{$arguments+=@('--manifest-sha',$ManifestSha256)}
$quoted=@($arguments|ForEach-Object{'"'+$_.Replace('"','\"')+'"'})
$executable=Join-Path $runnerPath 'ValidationBenchmark.exe';$stdout=Join-Path $launchPath 'stdout.txt';$stderr=Join-Path $launchPath 'stderr.txt'
$process=Start-Process -FilePath $executable -ArgumentList $quoted -WorkingDirectory $runnerPath -WindowStyle Hidden -RedirectStandardOutput $stdout -RedirectStandardError $stderr -PassThru
$request=[ordered]@{State='launched';Utc=[DateTime]::UtcNow.ToString('O');ProcessId=$process.Id;Executable=$executable;PinSha256=(Get-FileHash -LiteralPath $pinPath -Algorithm SHA256).Hash;Arguments=$arguments;Inputs=$inputsPath;ManifestSha256=$ManifestSha256;Evidence=$evidencePath;Stdout=$stdout;Stderr=$stderr;Owner=$(if($PreparationSelfCheck){'Preparation worker bounded3x24 self-check'}else{'Codex controller; monitor process and durable completed/failed receipts, no automatic retry'});PotentialSeconds=$(if($PreparationSelfCheck){'Bounded small3x24 self-check only'}else{'May exceed600; controller-owned full workload'})}
[IO.File]::WriteAllText((Join-Path $launchPath 'request.json'),($request|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false));$request|ConvertTo-Json -Depth 8
